//! The wire is the one Curriculum already speaks. Each fixture is a frame
//! recorded between the curriculum CLI and the Curriculum Nexus built from
//! Curriculum e3ffb31, whose Query and Outcome were generated by ethos-zero
//! 22 before this contract existed: each reads as the Input or Output it
//! was, and archives back to the same bytes.

use signal_curriculum_nexus::{
    CallerMetaflow, Input, ModuleIdentity, Output, RoleName, RoleSelection, StartupSelection,
    Surface, SystemModules, Target, UserModules,
};

const RESOLVE_SKILLS: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/resolve-skills.query");
const RESOLVED_SKILLS: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/resolve-skills.reply");
const RESOLVE_SOURCES: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/resolve-sources.query");
const RESOLVED_SOURCES: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/resolve-sources.reply");
const COMPOSE_STARTUP: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/compose-startup.query");
const COMPOSE_ROLE: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/compose-role.query");
const COMPOSE_UNKNOWN_ROLE: &[u8] =
    include_bytes!("fixtures/curriculum-e3ffb31/compose-role-unknown.query");
const REJECTED: &[u8] = include_bytes!("fixtures/curriculum-e3ffb31/compose-role-unknown.reply");

fn input(frame: &[u8]) -> Input {
    let input = rkyv::from_bytes::<Input, rkyv::rancor::Error>(frame).expect("an Input frame");
    assert_eq!(
        rkyv::to_bytes::<rkyv::rancor::Error>(&input)
            .expect("archive input")
            .as_slice(),
        frame
    );
    input
}

fn output(frame: &[u8]) -> Output {
    let output = rkyv::from_bytes::<Output, rkyv::rancor::Error>(frame).expect("an Output frame");
    assert_eq!(
        rkyv::to_bytes::<rkyv::rancor::Error>(&output)
            .expect("archive output")
            .as_slice(),
        frame
    );
    output
}

fn core() -> Vec<ModuleIdentity> {
    vec![ModuleIdentity("spirit:core:0".into())]
}

#[test]
fn the_published_inputs_read_and_archive_back() {
    assert_eq!(input(RESOLVE_SKILLS), Input::ResolveSkills(core()));
    assert_eq!(input(RESOLVE_SOURCES), Input::ResolveSources(core()));
    assert_eq!(
        input(COMPOSE_STARTUP),
        Input::ComposeStartup(StartupSelection {
            caller_metaflow: CallerMetaflow {
                first_string: "Mind".into(),
                second_string: "curriculum".into(),
                third_string: "Opus".into(),
            },
            target: Target::Codex,
            system_modules: SystemModules(vec![
                ModuleIdentity("spirit:core:0".into()),
                ModuleIdentity("intent:design:0".into()),
            ]),
            user_modules: UserModules(vec![ModuleIdentity("knowledge:psyche:0".into())]),
            flow_id_vector: vec![],
        })
    );
    assert_eq!(
        input(COMPOSE_ROLE),
        Input::ComposeRole(RoleSelection {
            role_name: RoleName("read-trivial".into()),
            surface: Surface::ClaudeAgent,
        })
    );
    assert_eq!(
        input(COMPOSE_UNKNOWN_ROLE),
        Input::ComposeRole(RoleSelection {
            role_name: RoleName("no-such-role".into()),
            surface: Surface::PiAgent,
        })
    );
}

#[test]
fn the_published_outputs_read_and_archive_back() {
    assert_eq!(output(RESOLVED_SKILLS), Output::SkillsResolved(core()));
    let Output::SourcesResolved(modules) = output(RESOLVED_SOURCES) else {
        panic!("SourcesResolved");
    };
    assert_eq!(
        modules
            .iter()
            .map(|module| module.module_identity.clone())
            .collect::<Vec<_>>(),
        core()
    );
    assert_eq!(
        output(REJECTED),
        Output::Rejected("unknown role/surface".into())
    );
}
